/* eslint-disable @next/next/no-img-element -- static decorative SVG, no optimisation needed */

/**
 * The lace doily from the client's studio food photos. One static, cached SVG
 * (generated by scripts/make-lace.mjs) instead of inlining the pierced pattern per photo.
 */
export function Lace({ className, tone = "milk" }: { className?: string; tone?: "milk" | "cream" }) {
  return (
    <img
      src={tone === "milk" ? "/brand/lace.svg" : "/brand/lace-cream.svg"}
      alt=""
      aria-hidden="true"
      className={className}
      width={200}
      height={200}
      decoding="async"
      draggable={false}
    />
  );
}
